#include <WiFi.h>
#include <PubSubClient.h>

const char* WIFI_SSID = "GANTI_SSID_2_4_GHZ";
const char* WIFI_PASSWORD = "GANTI_PASSWORD_WIFI";
const char* MQTT_HOST = "192.168.1.10";
const char* MQTT_USER = "esp32";
const char* MQTT_PASSWORD = "GANTI_PASSWORD_ESP32";
const char* DATA_TOPIC = "lab/esp32-01/telemetry";
const char* COMMAND_TOPIC = "lab/esp32-01/command";
WiFiClient network; // TCP tanpa TLS, khusus LAN lab.
PubSubClient mqtt(network);
unsigned long lastWifiTry = 0, lastMqttTry = 0, lastSend = 0;

void received(char* topic, byte* payload, unsigned int length) {
  // Payload bukan string berakhiran nol; baca berdasarkan panjang.
  Serial.print("Perintah pada "); Serial.print(topic); Serial.print(": ");
  for (unsigned int i = 0; i < length; i++) Serial.write(payload[i]);
  Serial.println(" (hanya ditampilkan, tidak mengendalikan beban)");
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  mqtt.setServer(MQTT_HOST, 1883);
  mqtt.setCallback(received);
  mqtt.setBufferSize(384);
  mqtt.setSocketTimeout(3);
  mqtt.setKeepAlive(30);
}

void loop() {
  unsigned long now = millis();
  if (WiFi.status() != WL_CONNECTED) {
    if (mqtt.connected()) mqtt.disconnect();
    if (now - lastWifiTry >= 10000UL) {
      lastWifiTry = now;
      WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
      Serial.println("Mencoba Wi-Fi kembali...");
    }
    return;
  }
  if (!mqtt.connected()) {
    if (now - lastMqttTry >= 5000UL) {
      lastMqttTry = now;
      // Client ID harus unik untuk setiap perangkat.
      if (mqtt.connect("esp32-01", MQTT_USER, MQTT_PASSWORD)) {
        Serial.println("MQTT terhubung");
        Serial.println(mqtt.subscribe(COMMAND_TOPIC) ? "Subscribe dikirim" : "Subscribe gagal");
      } else {
        Serial.print("MQTT gagal, state="); Serial.println(mqtt.state());
      }
    }
    return;
  }
  mqtt.loop(); // Layani pesan masuk dan keepalive sesering mungkin.
  if (now - lastSend >= 5000UL) {
    lastSend = now;
    // Nilai simulasi, BUKAN pembacaan sensor.
    float temperature = 26.0f + ((now / 5000UL) % 6);
    char payload[160];
    snprintf(payload, sizeof(payload),
      "{\"deviceId\":\"esp32-01\",\"temperature\":%.1f,\"unit\":\"C\",\"simulated\":true}",
      temperature);
    // PubSubClient publish memakai QoS 0. Tidak ada antrean offline.
    bool sent = mqtt.publish(DATA_TOPIC, payload, false);
    Serial.println(sent ? payload : "Publish gagal");
  }
}

