import json
import math
import os
import queue
import threading
import time

import firebase_admin
from firebase_admin import credentials, db
import paho.mqtt.client as mqtt

TOPIC = "lab/esp32-01/telemetry"
PATH = "devices/esp32-01/latest"
pending = queue.Queue(maxsize=1)  # Hanya nilai terbaru, bukan riwayat.

def parse_telemetry(payload):
    if len(payload) > 512:
        raise ValueError("payload terlalu besar")
    value = json.loads(payload.decode("utf-8"))
    if not isinstance(value, dict):
        raise ValueError("payload harus objek")
    if value.get("deviceId") != "esp32-01" or value.get("unit") != "C":
        raise ValueError("identitas atau unit salah")
    temp = value.get("temperature")
    if type(temp) not in (int, float) or not math.isfinite(temp) or not -40 <= temp <= 125:
        raise ValueError("suhu tidak valid")
    if type(value.get("simulated")) is not bool:
        raise ValueError("penanda simulasi harus boolean")
    return {"deviceId": "esp32-01", "temperature": temp,
            "unit": "C", "simulated": value["simulated"]}

def write_latest(reference):
    while True:
        data = pending.get()
        for attempt in range(3):
            try:
                reference.set({**data, "receivedAt": {".sv": "timestamp"}})
                print("Tersimpan:", data["temperature"], "C", flush=True)
                break
            except Exception as error:
                # Jangan cetak kredensial atau isi file kunci dalam log.
                print("Tulis Firebase gagal:", type(error).__name__, flush=True)
                if attempt < 2:
                    time.sleep(2 ** attempt)
        else:
            print("Nilai dilewati setelah 3 percobaan; tunggu nilai baru.", flush=True)
        pending.task_done()

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code.is_failure:
        print("Login MQTT ditolak:", reason_code, flush=True)
        return
    client.subscribe(TOPIC, qos=1)  # Subscribe ulang saat reconnect.
    print("MQTT terhubung; subscription diminta.", flush=True)

def on_message(client, userdata, message):
    if message.topic != TOPIC:
        return
    try:
        data = parse_telemetry(message.payload)
    except (ValueError, UnicodeError, OverflowError, RecursionError):
        print("Pesan ditolak: format/isi tidak valid.", flush=True)
        return
    # Callback MQTT tidak menunggu permintaan Firebase selesai.
    try:
        pending.put_nowait(data)
    except queue.Full:
        try:
            pending.get_nowait()
            pending.task_done()
        except queue.Empty:
            pass
        pending.put_nowait(data)

def main():
    url = os.environ["FIREBASE_DATABASE_URL"].rstrip("/")
    if not url.startswith("https://"):
        raise ValueError("Gunakan URL HTTPS Realtime Database dari console")
    cred = credentials.Certificate(os.environ["GOOGLE_APPLICATION_CREDENTIALS"])
    firebase_admin.initialize_app(cred, {
        "databaseURL": url,
        "databaseAuthVariableOverride": {"uid": "mqtt-bridge"},
        "httpTimeout": 10,
    })
    reference = db.reference(PATH)
    threading.Thread(target=write_latest, args=(reference,), daemon=True).start()
    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2, client_id="firebase-bridge-01")
    client.username_pw_set("bridge", os.environ["MQTT_PASSWORD"])
    client.on_connect = on_connect
    client.on_message = on_message
    client.reconnect_delay_set(min_delay=1, max_delay=30)
    client.connect_async(os.environ.get("MQTT_HOST", "192.168.1.10"), 1883, 60)
    try:
        client.loop_forever(retry_first_connection=True)
    except KeyboardInterrupt:
        client.disconnect()

if __name__ == "__main__":
    main()

import { initializeApp } from "firebase/app";
import { getAuth, signInWithEmailAndPassword, signOut, onAuthStateChanged } from "firebase/auth";
import { getDatabase, ref, onValue } from "firebase/database";

// Salin konfigurasi aplikasi WEB milik project latihan Anda.
// Konfigurasi web bukan service-account JSON dan bukan password akun.
const firebaseConfig = {
  apiKey: "GANTI_API_KEY_WEB",
  authDomain: "GANTI_PROJECT.firebaseapp.com",
  databaseURL: "https://GANTI_URL_INSTANCE_DATABASE",
  projectId: "GANTI_PROJECT",
  appId: "GANTI_APP_ID"
};
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const database = getDatabase(app);
const el = id => document.getElementById(id);
let stopListening = null;
let latest = null;

function showData() {
  if (!latest) {
    el("temperature").textContent = "—";
    el("kind").textContent = "Belum ada data yang dapat ditampilkan";
    el("freshness").textContent = "—";
    el("timestamp").textContent = "—";
    return;
  }
  el("temperature").textContent = `${latest.temperature.toFixed(1)} °C`;
  el("kind").textContent = latest.simulated ? "Data SIMULASI, bukan sensor asli" : "Data sensor";
  const age = Math.max(0, Math.floor((Date.now() - latest.receivedAt) / 1000));
  el("freshness").textContent = age > 20
    ? `Data lama: ${age} detik sejak penerimaan; periksa alur koneksi.`
    : `Data baru: ${age} detik sejak penerimaan.`;
  el("timestamp").textContent = `Diterima database: ${new Date(latest.receivedAt).toLocaleString("id-ID")}`;
}

el("login").addEventListener("submit", async event => {
  event.preventDefault();
  el("submit").disabled = true;
  el("status").textContent = "Memeriksa akun…";
  try {
    await signInWithEmailAndPassword(auth, el("email").value.trim(), el("password").value);
    el("password").value = "";
  } catch {
    el("status").textContent = "Masuk gagal. Periksa akun, provider Email/Password, dan konfigurasi project.";
  } finally {
    el("submit").disabled = false;
  }
});
el("logout").addEventListener("click", () => {
  signOut(auth).catch(() => { el("status").textContent = "Keluar gagal; coba kembali."; });
});
onAuthStateChanged(auth, user => {
  if (stopListening) stopListening();
  stopListening = null;
  latest = null;
  showData();
  el("login").hidden = Boolean(user);
  el("logout").hidden = !user;
  if (!user) {
    el("status").textContent = "Masuk memakai akun pembaca latihan.";
    return;
  }
  el("status").textContent = "Login berhasil; menunggu data…";
  stopListening = onValue(ref(database, "devices/esp32-01/latest"), snapshot => {
    const value = snapshot.val();
    if (!value || value.deviceId !== "esp32-01" || value.unit !== "C" ||
        typeof value.temperature !== "number" || !Number.isFinite(value.temperature) ||
        typeof value.receivedAt !== "number" || !Number.isFinite(value.receivedAt) ||
        typeof value.simulated !== "boolean") {
      latest = null;
      el("status").textContent = "Data belum tersedia atau formatnya tidak sesuai.";
    } else {
      latest = value;
      el("status").textContent = "Nilai terakhir berhasil dibaca. Pantau umur data di bawah.";
    }
    showData();
  }, () => {
    latest = null;
    showData();
    el("status").textContent = "Baca ditolak/gagal. Periksa UID pembaca, path, rules, dan koneksi.";
  });
});
// Umur data tetap bertambah meskipun tidak ada event Firebase baru.
setInterval(showData, 1000);
